import{_ as t,o,c as a,a3 as s}from"./chunks/framework.DH50UWNB.js";const k=JSON.parse('{"title":"Codex","description":"","frontmatter":{},"headers":[],"relativePath":"agents/codex.md","filePath":"agents/codex.md"}'),d={name:"agents/codex.md"};function i(n,e,c,h,l,r){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="codex" tabindex="-1">Codex <a class="header-anchor" href="#codex" aria-label="Permalink to &quot;Codex&quot;">​</a></h1><p>Connect a repository to Codex from its directory:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line prompt"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wake</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> connect</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> codex</span></span></code></pre></div><p><code>wake setup --agent codex</code> runs it for you. Commit the files it writes.</p><h2 id="what-you-get" tabindex="-1">What you get <a class="header-anchor" href="#what-you-get" aria-label="Permalink to &quot;What you get&quot;">​</a></h2><p>Five commands, which Codex installs as skills. Type <code>$</code> and the skill&#39;s name in Codex, such as <code>$wake-next</code>, or pick it from <code>/skills</code>:</p><table tabindex="0"><thead><tr><th>Command</th><th>What it does</th></tr></thead><tbody><tr><td><code>$wake-next</code></td><td>Proposes the next free task and claims it once you confirm</td></tr><tr><td><code>$wake-status</code></td><td>Shows the tasks this session holds, the free ones and what is left in the open milestone; changes nothing</td></tr><tr><td><code>$wake-plan &lt;idea&gt;</code></td><td>Plans the idea with the repository&#39;s planning method, without writing code</td></tr><tr><td><code>$wake-done</code></td><td>Runs the repository&#39;s checks, attaches evidence and completes the task this session holds</td></tr><tr><td><code>$wake-release</code></td><td>Releases the open milestone with the repository&#39;s own process, asking before every push, tag or publish</td></tr></tbody></table><p>The <code>wake</code> and <code>wake-planning</code> skills tell Codex how to claim, plan and finish work. Hooks run <code>wake hook</code> when a session starts, after each tool call and when it ends, with the <a href="/wake-dist/docs/start/cli#sign-in">CLI&#39;s sign-in</a>, so the CLI must be installed and signed in on this machine.</p><h2 id="files-it-writes" tabindex="-1">Files it writes <a class="header-anchor" href="#files-it-writes" aria-label="Permalink to &quot;Files it writes&quot;">​</a></h2><ul><li><code>.codex/config.toml</code>: Wake&#39;s MCP server, the <code>[mcp_servers.wake]</code> table, at <code>&lt;your Wake URL&gt;/mcp</code>. Only that table changes; the rest of the file stays as it was.</li><li><code>.codex/hooks.json</code>: the hooks, merged with yours.</li><li><code>.agents/skills/wake-next/SKILL.md</code>, <code>wake-status</code>, <code>wake-plan</code>, <code>wake-done</code> and <code>wake-release</code>: the commands.</li><li><code>.agents/skills/wake/SKILL.md</code> and <code>.agents/skills/wake-planning/SKILL.md</code>: the skills, one copy shared with OpenCode and Pi.</li><li>The Wake block in <code>AGENTS.md</code>, created when the repository has none.</li></ul><p>No file holds a token.</p><h2 id="sign-in" tabindex="-1">Sign in <a class="header-anchor" href="#sign-in" aria-label="Permalink to &quot;Sign in&quot;">​</a></h2><ol><li>Open Codex in the repository and trust the project when it asks.</li><li>Review and trust Wake&#39;s hooks with <code>/hooks</code>.</li><li>Run <code>codex mcp login wake</code> and allow Codex in the browser.</li></ol><h2 id="updates" tabindex="-1">Updates <a class="header-anchor" href="#updates" aria-label="Permalink to &quot;Updates&quot;">​</a></h2><p>The CLI updates Codex&#39;s files. After you <a href="/wake-dist/docs/start/cli#update-the-cli">update the CLI</a>, the next session start brings the files above up to the CLI&#39;s version, as <code>wake connect codex</code> would, and the agent&#39;s context names the files to commit. It skips the update when you edited one of those files, or when they come from a newer Wake than your CLI, and says why instead: it never overwrites an edit or downgrades a teammate.</p><p>To update only by hand, set <code>WAKE_ADAPTER_UPDATES=off</code> in the agent&#39;s environment. The session start then says to run <code>wake connect codex</code> when a newer version is available.</p>',16)])])}const w=t(d,[["render",i]]);export{k as __pageData,w as default};
